    internal static MultipartBody Attachment(string fileName)
    {
        var body = new MultipartBody();
        body.AddOrReplacePart("file", "image/png", new MemoryStream(Convert.FromBase64String(
            "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+ip1sAAAAASUVORK5CYII=")), fileName);
        return body;
    }
